package commentscan

import "testing"

func TestScanGoSkipsDirectives(t *testing.T) {
	src := []byte(`//go:build linux

// Code generated by tool. DO NOT EDIT.

package demo

//go:embed asset.txt
var asset string

// Counted explains nothing.
// It spans two lines.
func Counted() {} // trailing

/*
block
*/
var x = 1 //nolint:unused
`)
	comments, err := ScanGo("demo.go", src)
	if err != nil {
		t.Fatal(err)
	}
	if len(comments) != 4 {
		t.Fatalf("comments = %d, want 4: %+v", len(comments), comments)
	}
	if got := Lines(comments); got != 6 {
		t.Fatalf("lines = %d, want 6", got)
	}
}

func TestScanGoRejectsInvalidSource(t *testing.T) {
	if _, err := ScanGo("bad.go", []byte("package")); err == nil {
		t.Fatal("want parse error")
	}
}

func TestScanGoIgnoresCommentMarkersInStrings(t *testing.T) {
	src := []byte("package demo\n\nvar s = \"// not a comment\"\nvar r = `/* raw */`\n")
	comments, err := ScanGo("demo.go", src)
	if err != nil {
		t.Fatal(err)
	}
	if len(comments) != 0 {
		t.Fatalf("comments = %+v, want none", comments)
	}
}
